      { params: '(1, 1, 0) (1, 0, 1)s', aic: 292, rmse: 17.41, mae: 9.32, mape: '99.9%', status: 'Config 2 (Runner-Up)', isRunnerUp: true },
      { params: '(1, 1, 1) (1, 0, 1)s', aic: 296, rmse: 18.20, mae: 9.85, mape: '99.9%', status: 'Evaluated' },
