    ],
    config1: { params: '(1, 0, 1) (0, 1, 1)s', aic: 162, rmse: 0.28, mae: 0.22, mape: '5.6%' },
    config2: { params: '(1, 1, 0) (1, 0, 1)s', aic: 168, rmse: 0.31, mae: 0.24, mape: '5.9%' },
