      { params: '(1, 1, 0) (1, 0, 1)s', aic: 160, rmse: 0.27, mae: 0.21, mape: '5.1%', status: 'Config 2 (Runner-Up)', isRunnerUp: true },
      { params: '(1, 1, 1) (1, 0, 1)s', aic: 165, rmse: 0.29, mae: 0.23, mape: '5.4%', status: 'Evaluated' },
